mapper.sql:
WHERE 
AND SD.ShopCode = #{shopCode}
AND Ch.SvcCode = #{svcCode}


    AND SD.ShipCheckDate >= DATE_FORMAT(#{startDate}, '%Y-%m-%d')
    AND SD.ShipCheckDate <  ADDDATE(DATE_FORMAT(#{endDate}, '%Y-%m-%d'), INTERVAL 1 DAY)

WHERE 
AND SD.ProdName NOT LIKE '힣%'
AND IFNULL(SD.OrderType, '') <> '사은품'
AND SD.ShopCode = #{shopCode}
AND Ch.SvcCode = #{svcCode}




            AND O.OrderReciptDate >= DATE_FORMAT(#{startDate}, '%Y-%m-%d')
            AND O.OrderReciptDate <  ADDDATE(DATE_FORMAT(#{endDate}, '%Y-%m-%d'), INTERVAL 1 DAY)




            AND SD.ShipCheckDate >= DATE_FORMAT(#{startDate}, '%Y-%m-%d')
            AND SD.ShipCheckDate <  ADDDATE(DATE_FORMAT(#{endDate}, '%Y-%m-%d'), INTERVAL 1 DAY)




AND SD.ChnlCode = #{chnlCode}
AND S.MngrMd = #{mdCode}
AND SD.ProdName LIKE CONCAT('%', #{prodName}, '%')

mapper.select:
SELECT SD.OrderNo AS orderNo, SD.OrderProdNo AS orderProdNo, SD.OrderChangeNo AS orderChangeNo, SD.ChnlOrderNo AS chnlOrderNo, CAST(O.OrderReciptDate AS CHAR) AS orderReciptDate, CAST(SD.ShipCheckDate AS CHAR) AS shipCheckDate, SD.RecverName AS recverName, SD.OrderState AS orderState, SD.ShopProdCode AS shopProdCode, IFNULL(SD.ProdMemo01, '') AS prodMemo01, SD.OrderProdName AS orderProdName, SD.ProdName AS prodName,
(SELECT OU.UnitName FROM shopwizard.tOrdOrderUprice OU WHERE OU.OrderProdName = SD.ProdName AND OU.UseYn = 1 ORDER BY OU.UnitName LIMIT 1) AS unitName, SD.ItemName AS itemName, SD.ProdQty AS prodQty, SD.OrderProdQty AS orderProdQty, SD.SalePrice AS salePrice, SD.NvPrice AS nvPrice, SD.SupplyPrice AS supplyPrice, SD.BuyPrice AS buyPrice, SD.DeliFeeAmt AS deliFeeAmt, SD.DeliFeeType AS deliFeeType, Ch.ChnlName AS chnlName, IFNULL(SD.BundleYn, 0) AS bundleYn, SD.RecverAddr AS recverAddr FROM shopwizard.tShpShipDirectPrint SD INNER JOIN shopion.tOrdOrder O ON SD.OrderNo = O.OrderNo INNER JOIN shopwizard.tCmpChnl Ch ON SD.ChnlCode = Ch.ChnlCode INNER JOIN shopwizard.tCmpShop S ON SD.ShopCode = S.ShopCode
ORDER BY SD.OrderNo, SD.OrderProdNo, SD.OrderChangeNo LIMIT #{offset}, #{limit}
